package com.railway.servlet;
import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import java.time.LocalDate;import com.railway.dao.TrainDao;import com.railway.util.Validation;
public class SearchServlet extends HttpServlet {protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{r.getRequestDispatcher("/search-trains.jsp").forward(r,s);}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{String src=r.getParameter("source"),dst=r.getParameter("destination"),date=r.getParameter("journeyDate");if(src==null||dst==null||src.isBlank()||dst.isBlank()||src.equalsIgnoreCase(dst)||!Validation.journeyDate(date)){r.setAttribute("error","Enter different source and destination stations and a valid date today or later.");doGet(r,s);return;}try{r.setAttribute("trains",new TrainDao().search(src,dst,LocalDate.parse(date)));r.setAttribute("source",src);r.setAttribute("destination",dst);r.setAttribute("journeyDate",date);r.getRequestDispatcher("/train-results.jsp").forward(r,s);}catch(Exception e){getServletContext().log("Train search failed",e);r.setAttribute("error","Train search is temporarily unavailable.");doGet(r,s);}}}
